from pathlib import Path
import subprocess,json,sys,statistics
ROOT=Path('/Users/chazu/dev/zig/birnam');WORK=Path('/tmp/birnam-runtime-tables')
sys.path.insert(0,str(ROOT/'scripts'))
from validation_support import clean_environment,save_json
prefixes={'baseline':Path('/tmp/birnam-scratch-state/prefix'),'candidate':WORK/'candidate'}
rows=[]
for sample in range(3):
 for label in (('baseline','candidate') if sample%2==0 else ('candidate','baseline')):
  for app in ('logue','json'):
   work=WORK/f'{label}-{app}-{sample}'
   if app=='logue':
    args=[sys.executable,str(ROOT/'scripts/logue-bench.py'),'--prefix',str(prefixes[label]),'--work',str(work),'--cases','crowded,quiet,generation','--samples','1']
    if sample:args+=['--skip-regression']
   else:args=[sys.executable,str(ROOT/'scripts/log-summary-profile.py'),'--prefix',str(prefixes[label]),'--work',str(work),'--iterations','5']
   log=WORK/f'{label}-{app}-{sample}.log'
   with log.open('w') as stream:
    run=subprocess.run(args,cwd=ROOT,env=clean_environment(),stdout=stream,stderr=subprocess.STDOUT,timeout=300)
   if run.returncode:raise RuntimeError(f'{label} {app}: {run.returncode}; {log}')
   record=json.loads((work/'results.json').read_text())
   if app=='logue':
    assert record['all_requested_passed']
    metrics={r['label']:r['median_cpu_ns'] for r in record['runs'] if 'median_cpu_ns' in r}
   else:metrics={r['phase']:statistics.median(s['cpu_ns'] for s in r['samples']) for r in record['runs']['time']['results']}
   rows.append({'variant':label,'app':app,'sample':sample,'metrics':metrics,'receipt':str(work/'results.json')})
   save_json(WORK/'comparison.json',{'runs':rows})
   print(label,app,sample,{k:round(v/1e6,2) for k,v in metrics.items()},flush=True)
print('all comparisons passed')
